def max_area(height: list[int]) -> int:
    left, right = 0, len(height) - 1
    max_w = 0
    while left < right:
        w = (right - left) * min(height[left], height[right])
        if w > max_w:
            max_w = w
        if height[left] < height[right]:
            left += 1
        else:
            right -= 1
    return max_w
